#!/bin/bash
fail=0
bash src/remind.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "remind: a malformed date should exit 2"; fail=1; }
[ "$(bash src/remind.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "remind: bad date message"; fail=1; }
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02)" = 'reminder to x: aoi 2026-01-02 10:00' ] || { echo "remind: a well-formed date should pass"; fail=1; }
rm -f "$t"; exit $fail

